using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; using Saldo360.Domain.Families; using Saldo360.Domain.Accounts; using Saldo360.Domain.Goals;
namespace Saldo360.Infrastructure.Persistence.Configurations;
internal sealed class FinancialGoalAllocationConfiguration:IEntityTypeConfiguration<FinancialGoalAllocation>{public void Configure(EntityTypeBuilder<FinancialGoalAllocation>b){b.ToTable("financial_goal_allocations",t=>{t.HasCheckConstraint("ck_goal_allocations_amount","amount > 0");});b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.Amount).HasPrecision(18,2);b.Property(x=>x.OperationType).HasConversion<int>();b.Property(x=>x.Description).HasMaxLength(FinancialGoalAllocation.DescriptionMaxLength);b.Property(x=>x.EffectiveDate).HasColumnType("date");b.HasIndex(x=>new{x.FamilyId,x.OperationId}).IsUnique();b.HasIndex(x=>new{x.FamilyId,x.GoalId,x.EffectiveDate});b.HasIndex(x=>new{x.FamilyId,x.FinancialAccountId,x.CancelledAt});b.HasAlternateKey(x=>new{x.FamilyId,x.Id});b.HasOne<Family>().WithMany().HasForeignKey(x=>x.FamilyId).OnDelete(DeleteBehavior.Restrict);b.HasOne<FinancialGoal>().WithMany().HasForeignKey(x=>new{x.FamilyId,x.GoalId}).HasPrincipalKey(x=>new{x.FamilyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<FinancialAccount>().WithMany().HasForeignKey(x=>new{x.FamilyId,x.FinancialAccountId}).HasPrincipalKey(x=>new{x.FamilyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
